0295a0e44107c207b87b9e07086d8d16b186fdc7:
query FlxHeadlessPosts($first: Int = 10, $after: String, $categoryId: Int, $tagId: String, $authorId: Int, $search: String) {
  posts(
    first: $first
    after: $after
    where: {
      categoryId: $categoryId
      tagId: $tagId
      author: $authorId
      search: $search
      status: PUBLISH
    }
  ) {
    pageInfo {
      hasNextPage
      endCursor
    }
    nodes {
      databaseId
      title
      uri
      date
      excerpt
      featuredImage {
        node {
          sourceUrl
          altText
          mediaDetails {
            width
            height
          }
        }
      }
    }
  }
}

30296117864b33574ff7752c3956fc9e9d6a3e2b:
query FlxHeadlessBlocks($id: ID!) {
  contentNode(id: $id, idType: DATABASE_ID) {
    __typename
    ... on Page {
      flxBlocks {
        html
        css
        headHtml
        footerHtml
        fonts
      }
    }
    ... on Post {
      flxBlocks {
        html
        css
        headHtml
        footerHtml
        fonts
      }
    }
  }
}

