96347f0382e8d56d558cde4aa572f53b02eb17c0:
query FlxRoute($path: String!, $lang: String, $frontend: ID, $previewId: Int) {
  flxRoute(path: $path, lang: $lang, frontend: $frontend, previewId: $previewId) {
    path
    kind
    status
    redirect
    lang
    title
    page
    databaseId
    postType
    taxonomy
    head {
      ...FlxHeadlessHeadFields
    }
    alternates {
      lang
      hreflang
      url
      path
    }
    cacheTags
    frontendId
    node {
      __typename
      uri
      ... on NodeWithTitle {
        title
      }
      ... on ContentNode {
        databaseId
        date
        modified
        contentTypeName
      }
      ... on NodeWithContentEditor {
        content
      }
      ... on NodeWithExcerpt {
        excerpt
      }
      ... on NodeWithFeaturedImage {
        featuredImage {
          node {
            sourceUrl
            altText
            mediaDetails {
              width
              height
            }
          }
        }
      }
      ... on NodeWithAuthor {
        author {
          node {
            name
          }
        }
      }
      ... on TermNode {
        databaseId
        name
        description
      }
      ... on User {
        databaseId
        name
        description
      }
    }
  }
}

fragment FlxHeadlessHeadFields on FlxHeadlessHead {
  title
  description
  canonical
  robots
  noindex
  image
  locale
  meta {
    name
    property
    content
  }
  jsonLd
}

